//! Everything extracted from one source file.

use std::fmt;

use camino::Utf8PathBuf;

use super::lang::AnalysisProfile;
use crate::digest::Digest;
use crate::types::{CodeBlock, DependencyRecord, ExportRecord, JsxElementEntry, LangData, SymbolEntry};

/// Why a file was analyzed without its content: the analyzer gave up on it instead of reading it.
///
/// A file with syntax errors is not degraded this way; its recovered content is kept and only
/// [`FileAnalysis::had_parse_errors`] is set.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum Degradation {
    /// The source is longer than the analyzer will parse.
    TooLarge {
        /// The length of the source.
        bytes: usize,
        /// The longest source the analyzer parses.
        cap: usize,
    },
    /// The parse or extraction panicked.
    Panicked,
    /// The analyzer could not start the thread the parse runs on.
    ThreadUnavailable,
}

impl fmt::Display for Degradation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooLarge { bytes, cap } => {
                write!(f, "file too large to parse ({bytes} bytes, over the cap of {cap})")
            }
            Self::Panicked => f.write_str("parser panicked"),
            Self::ThreadUnavailable => f.write_str("could not start a parse thread"),
        }
    }
}

/// The result of analyzing one file.
///
/// It owns all its data, so it can outlive the parse that produced it. Under [`AnalysisProfile::Dependencies`] only
/// `dependencies` is filled; under [`AnalysisProfile::Structural`] `blocks` is empty. `profile` records which, so a
/// cache never serves a partial result as a full one.
#[derive(Clone, Debug)]
pub struct FileAnalysis {
    pub source_path: Utf8PathBuf,
    pub digest: Digest,
    pub profile: AnalysisProfile,
    /// Set for any file that did not parse cleanly, including every file with a [`Degradation`].
    pub had_parse_errors: bool,
    /// Why the file's content is missing, when the analyzer gave up on it.
    pub degradation: Option<Degradation>,
    pub symbols: Vec<SymbolEntry>,
    pub dependencies: Vec<DependencyRecord>,
    pub exports: Vec<ExportRecord>,
    pub blocks: Vec<CodeBlock>,
    pub lang: LangData,
}

impl FileAnalysis {
    /// The language name, matching the tag `LangData` serializes with.
    #[must_use]
    pub fn language(&self) -> &str {
        match &self.lang {
            LangData::Ts(_) => "typescript",
            LangData::Rust(_) => "rust",
            LangData::Python(_) => "python",
            LangData::Go(_) => "go",
            LangData::Java(_) => "java",
        }
    }

    /// The JSX elements of a TypeScript file, or an empty slice for any other language.
    #[must_use]
    pub fn jsx_elements(&self) -> &[JsxElementEntry] {
        self.lang.jsx_elements()
    }

    /// Whether this is a TypeScript file.
    #[must_use]
    pub fn is_typescript(&self) -> bool {
        matches!(self.lang, LangData::Ts(_))
    }
}

#[cfg(test)]
mod tests {
    use rstest::rstest;

    use super::*;
    use crate::types::{GoData, JavaData, PythonData, RustData, TsData};

    fn analysis(lang: LangData) -> FileAnalysis {
        FileAnalysis {
            source_path: Utf8PathBuf::from("src/a.ts"),
            digest: Digest::blake3(b"x"),
            profile: AnalysisProfile::Structural,
            had_parse_errors: true,
            degradation: None,
            symbols: Vec::new(),
            dependencies: Vec::new(),
            exports: Vec::new(),
            blocks: Vec::new(),
            lang,
        }
    }

    fn jsx(name: &str) -> JsxElementEntry {
        JsxElementEntry { name: name.to_string(), is_html: false, line: 1, attributes: Vec::new() }
    }

    #[rstest]
    #[case(LangData::Ts(TsData::default()), "typescript", true)]
    #[case(LangData::Rust(RustData::default()), "rust", false)]
    #[case(LangData::Python(PythonData::default()), "python", false)]
    #[case(LangData::Go(GoData::default()), "go", false)]
    #[case(LangData::Java(JavaData::default()), "java", false)]
    fn language_names_follow_the_lang_data_variant(
        #[case] lang: LangData,
        #[case] name: &str,
        #[case] typescript: bool,
    ) {
        let analysis = analysis(lang);
        assert_eq!(analysis.language(), name);
        assert_eq!(analysis.is_typescript(), typescript);
        assert!(analysis.jsx_elements().is_empty());
    }

    #[rstest]
    #[case(Degradation::TooLarge { bytes: 300_000, cap: 260_096 }, "file too large to parse (300000 bytes, over the cap of 260096)")]
    #[case(Degradation::Panicked, "parser panicked")]
    #[case(Degradation::ThreadUnavailable, "could not start a parse thread")]
    fn a_degradation_names_its_reason(#[case] degradation: Degradation, #[case] text: &str) {
        assert_eq!(degradation.to_string(), text);
    }

    #[test]
    fn typescript_files_expose_their_jsx_elements_in_order() {
        let ts = TsData { jsx_elements: vec![jsx("App"), jsx("Button")], ..TsData::default() };
        let analysis = analysis(LangData::Ts(ts));
        let names: Vec<_> = analysis.jsx_elements().iter().map(|e| e.name.as_str()).collect();
        assert_eq!(names, ["App", "Button"]);
    }

    fn assert_owned<T: Clone + std::fmt::Debug + Send + Sync + 'static>(_: &T) {}

    #[test]
    fn a_file_analysis_is_owned_and_clones_faithfully() {
        let original = analysis(LangData::Ts(TsData::default()));
        assert_owned(&original);
        let clone = original.clone();
        assert_eq!(clone.source_path, original.source_path);
        assert_eq!(clone.digest, original.digest);
        assert_eq!(clone.profile, AnalysisProfile::Structural);
        assert_eq!(clone.had_parse_errors, original.had_parse_errors);
        assert_eq!(clone.degradation, original.degradation);
        assert_eq!(format!("{clone:?}"), format!("{original:?}"));
    }
}
//! Agent-facing output: TOON projections of command results and conversion of [`MonoklError`] into michi errors.
use std::collections::BTreeMap;

use camino::Utf8Path;
use michi::toon::Value;

use crate::error::MonoklError;
use crate::types::{Diagnostic, DiagnosticKind, SymbolKind, Visibility};

/// The CLI command currently executing, so a recovery hint can name the right tool to retry.
pub struct ErrorContext<'a> {
    pub command: &'a str,
}

/// Converts a string into a TOON cell value.
///
/// The string is passed through unchanged: michi quotes and escapes control characters when it renders the row, so
/// escaping here as well would double-escape them.
pub fn cell(s: &str) -> Value {
    Value::from(s)
}

/// Like [`cell`], but maps `None` to [`Value::Null`].
pub fn opt_cell(s: Option<&str>) -> Value {
    match s {
        None => Value::Null,
        Some(s) => cell(s),
    }
}

#[cfg(test)]
mod cell_tests {
    use super::*;

    #[test]
    fn cell_plain_string_passes_through() {
        assert_eq!(cell("hello"), Value::from("hello"));
    }

    #[test]
    fn cell_leaves_line_breaks_for_michi_to_escape() {
        assert_eq!(cell("line1\r\nline2"), Value::from("line1\r\nline2"));
    }

    #[test]
    fn opt_cell_none_is_null() {
        assert_eq!(opt_cell(None), Value::Null);
    }

    #[test]
    fn opt_cell_some_empty_is_not_null() {
        assert_eq!(opt_cell(Some("")), Value::from(""));
        assert_ne!(opt_cell(Some("")), Value::Null);
    }

    // `cell` relies on michi escaping line breaks; if michi stops, multi-line code would break TOON rows.
    #[test]
    fn michi_escape_value_escapes_line_breaks() {
        let escaped = michi::toon::escape_value("// comment\r\nfn body() {\n}");
        assert_eq!(escaped, "\"// comment\\r\\nfn body() {\\n}\"");
    }
}

/// Returns the same `camelCase` name that serde produces for a [`SymbolKind`].
pub fn symbol_kind_str(k: SymbolKind) -> &'static str {
    match k {
        SymbolKind::Function => "function",
        SymbolKind::Method => "method",
        SymbolKind::Constructor => "constructor",
        SymbolKind::Class => "class",
        SymbolKind::Struct => "struct",
        SymbolKind::Enum => "enum",
        SymbolKind::Interface => "interface",
        SymbolKind::TypeAlias => "typeAlias",
        SymbolKind::Property => "property",
        SymbolKind::Field => "field",
        SymbolKind::Variable => "variable",
        SymbolKind::Module => "module",
        SymbolKind::Impl => "impl",
        SymbolKind::Macro => "macro",
        SymbolKind::Other => "other",
    }
}

/// Returns the same `camelCase` name that serde produces for a [`Visibility`].
pub fn visibility_str(v: Visibility) -> &'static str {
    match v {
        Visibility::Public => "public",
        Visibility::Crate => "crate",
        Visibility::Module => "module",
        Visibility::Private => "private",
    }
}

#[cfg(test)]
mod kind_str_tests {
    use super::*;

    #[test]
    fn symbol_kind_str_matches_serde_camel_case_form() {
        assert_eq!(symbol_kind_str(SymbolKind::Function), "function");
        assert_eq!(symbol_kind_str(SymbolKind::Method), "method");
        assert_eq!(symbol_kind_str(SymbolKind::Constructor), "constructor");
        assert_eq!(symbol_kind_str(SymbolKind::Class), "class");
        assert_eq!(symbol_kind_str(SymbolKind::Struct), "struct");
        assert_eq!(symbol_kind_str(SymbolKind::Enum), "enum");
        assert_eq!(symbol_kind_str(SymbolKind::Interface), "interface");
        assert_eq!(symbol_kind_str(SymbolKind::TypeAlias), "typeAlias");
        assert_eq!(symbol_kind_str(SymbolKind::Property), "property");
        assert_eq!(symbol_kind_str(SymbolKind::Field), "field");
        assert_eq!(symbol_kind_str(SymbolKind::Variable), "variable");
        assert_eq!(symbol_kind_str(SymbolKind::Module), "module");
        assert_eq!(symbol_kind_str(SymbolKind::Impl), "impl");
        assert_eq!(symbol_kind_str(SymbolKind::Macro), "macro");
        assert_eq!(symbol_kind_str(SymbolKind::Other), "other");
    }

    #[test]
    fn visibility_str_matches_serde_camel_case_form() {
        assert_eq!(visibility_str(Visibility::Public), "public");
        assert_eq!(visibility_str(Visibility::Crate), "crate");
        assert_eq!(visibility_str(Visibility::Module), "module");
        assert_eq!(visibility_str(Visibility::Private), "private");
    }
}

/// A command result that renders as a TOON table with `N` columns.
///
/// The column count is a const generic so a row with the wrong arity cannot be constructed.
pub trait ToonProjection<const N: usize> {
    /// The table name.
    const TYPE_NAME: &'static str;
    /// The column names.
    const FIELDS: [&'static str; N];
